"use client"

// Bollard UI — ai-citation-check · MIT licence · https://bollard-ui.vercel.app/components/ai-citation-check

import * as React from "react"
import { BookOpen, Bot, Check, CircleHelp, ExternalLink, Link2, Loader2, Quote, Scale, Trash2, Wrench, XCircle } from "lucide-react"
import { AnimatePresence, animate, motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"

import { applyFix, findReferences, type IssueCode, type RefKind, type Reference } from "./citations"

export { applyFix, findReferences, type Issue, type IssueCode, type RefKind, type Reference } from "./citations"

export const AI_CITATION_CHECK_MESSAGES = {
  summary: "{bad} look made up · {unverified} unverified · {ok} verified",
  none: "No references, links or quotes to check yet.",
  status: { bad: "Looks made up", missing: "Not found", off: "Exists, details off", unverified: "Unverified", verified: "Verified", checking: "Checking…" },
  missing: "No record of this in {source}.",
  kind: { doi: "DOI", case: "Case", url: "Link", cite: "Citation", quote: "Quote", marker: "Chatbot marker" } satisfies Record<RefKind, string>,
  /** Optional translations of each reason; {vars} come from the issue. Leave empty to use the built-in English. */
  issue: {} as Partial<Record<IssueCode, string>>,
  fix: "Use hyphens",
  remove: "Remove",
  show: "Show",
  more: "Show {count} more",
  submit: "Submit",
  submitAnyway: "Submit anyway",
  confirm: "{count} reference may not exist. Press again to submit it as is.|{count} references may not exist. Press again to submit them as is.",
  submitting: "Submitting…",
}

type Messages = typeof AI_CITATION_CHECK_MESSAGES
type Status = keyof Messages["status"]
/** What a lookup found. `true`/`false` are shorthand for found/not found. */
export type VerifyResult = boolean | { status: "found" | "not-found"; title?: string; url?: string }

export interface AiCitationCheckProps extends Omit<React.ComponentProps<"textarea">, "value" | "defaultValue" | "onChange" | "onSubmit"> {
  /** Controlled text. */
  value?: string
  /** Initial text when uncontrolled. */
  defaultValue?: string
  /** Called with the new text on every edit or fix. */
  onValueChange?: (value: string) => void
  /** Looks a reference up (Crossref for DOIs, CourtListener for cases, a HEAD request for links). Rejections show as Unverified. */
  verify?: (ref: Reference, signal: AbortSignal) => Promise<VerifyResult>
  /** Named in "No record of this in …". */
  sourceName?: string
  /** The current year, for "hasn't happened yet". Defaults to the device's year. */
  year?: number
  /** Called on submit. May return a Promise. Anything made up or unverified needs a second press. */
  onSubmit?: (value: string) => void | Promise<void>
  /** References listed before "Show N more". Default 5. */
  maxVisible?: number
  /** Class for the outer wrapper. */
  className?: string
  /** Class for the textarea. */
  textareaClassName?: string
  /** Override any visible string. */
  messages?: Partial<Omit<Messages, "status" | "kind">> & { status?: Partial<Messages["status"]>; kind?: Partial<Messages["kind"]> }
}

type Lookup = { state: "checking" | "found" | "not-found" | "error"; title?: string; url?: string }

const fill = (t: string, v: Record<string, string | number>) =>
  (t.includes("|") ? t.split("|")[Number(v.count) === 1 ? 0 : 1] : t).replace(/\{(\w+)\}/g, (k, key: string) => String(v[key] ?? k))
const chip = "inline-flex h-7 items-center gap-1 rounded-md border bg-background px-2.5 text-xs font-medium outline-none transition-colors hover:bg-accent focus-visible:ring-[3px] focus-visible:ring-ring/50 dark:bg-input/30"
const ICON: Record<RefKind, typeof Bot> = { doi: BookOpen, case: Scale, url: Link2, cite: BookOpen, quote: Quote, marker: Bot }
const TONE: Record<Status, string> = {
  bad: "border-red-500/40 bg-red-500/5 dark:bg-red-500/10",
  missing: "border-red-500/40 bg-red-500/5 dark:bg-red-500/10",
  off: "border-amber-500/40 bg-amber-500/5 dark:bg-amber-500/10",
  unverified: "border-amber-500/40 bg-amber-500/5 dark:bg-amber-500/10",
  verified: "border-emerald-500/30",
  checking: "",
}
const PILL: Record<Status, string> = {
  bad: "text-red-700 dark:text-red-400",
  missing: "text-red-700 dark:text-red-400",
  off: "text-amber-700 dark:text-amber-400",
  unverified: "text-amber-700 dark:text-amber-400",
  verified: "text-emerald-700 dark:text-emerald-400",
  checking: "text-muted-foreground",
}
const RANK: Record<Status, number> = { bad: 0, missing: 0, off: 1, unverified: 2, checking: 3, verified: 4 }

/**
 * Stops made-up references going out in AI-written text (the ChatGPT cases in Mata v. Avianca; Deloitte's
 * refunded government report). It flags the tells with reasons — a DOI prefix that isn't the named journal's
 * publisher, a long dash inside a DOI, F.3d cited for a post-2021 case, a future year, leftover oaicite
 * markers, long quotes with no source — looks each one up through a pluggable `verify`, and calls anything
 * it couldn't confirm "Unverified", never fine. Dashes and markers are fixed in one tap.
 */
export function AiCitationCheck({
  value: valueProp, defaultValue = "", onValueChange, verify, sourceName = "the lookup", year, onSubmit, maxVisible = 5, className, textareaClassName, messages,
  id: idProp, "aria-describedby": describedBy, onBlur, ...props
}: AiCitationCheckProps) {
  const m: Messages = { ...AI_CITATION_CHECK_MESSAGES, ...messages, status: { ...AI_CITATION_CHECK_MESSAGES.status, ...messages?.status }, kind: { ...AI_CITATION_CHECK_MESSAGES.kind, ...messages?.kind } }
  const [inner, setInner] = React.useState(defaultValue)
  const value = valueProp ?? inner
  const [checked, setChecked] = React.useState(value)
  const [lookups, setLookups] = React.useState<Record<string, Lookup>>({})
  const [all, setAll] = React.useState(false)
  const [armed, setArmed] = React.useState(false)
  const [submitting, setSubmitting] = React.useState(false)
  const [status, setStatus] = React.useState("")
  const fieldRef = React.useRef<HTMLTextAreaElement>(null)
  const listRef = React.useRef<HTMLUListElement>(null)
  const submitRef = React.useRef<HTMLButtonElement>(null)
  const asked = React.useRef(new Set<string>())
  const reduce = useReducedMotion()
  const auto = React.useId()
  const id = idProp ?? auto

  React.useEffect(() => {
    if (value === checked) return
    const t = setTimeout(() => setChecked(value), 800)
    return () => clearTimeout(t)
  }, [value, checked])

  const refs = React.useMemo(() => findReferences(checked.replace(/\r\n?/g, "\n"), { year }), [checked, year])

  // Look up each key once, three at a time. Results belong to the key, not the text, so edits elsewhere never discard them.
  const verifyRef = React.useRef(verify)
  verifyRef.current = verify
  const canVerify = !!verify
  React.useEffect(() => {
    if (!canVerify) return
    const todo = [...new Set(refs.map((r) => r.key).filter((k): k is string => !!k && !asked.current.has(k)))]
    if (!todo.length) return
    const ctrl = new AbortController()
    const pending = new Set(todo)
    todo.forEach((k) => asked.current.add(k))
    setLookups((l) => ({ ...l, ...Object.fromEntries(todo.map((k) => [k, { state: "checking" } as Lookup])) }))
    const queue = todo.map((k) => refs.find((r) => r.key === k)!)
    const worker = async () => {
      for (let ref = queue.shift(); ref; ref = queue.shift()) {
        const key = ref.key!
        let next: Lookup
        try {
          const r = await verifyRef.current!(ref, ctrl.signal)
          next = typeof r === "boolean" ? { state: r ? "found" : "not-found" } : { state: r?.status === "found" ? "found" : "not-found", title: r?.title, url: r?.url }
        } catch {
          next = { state: "error" }
        }
        if (ctrl.signal.aborted) continue
        pending.delete(key)
        setLookups((l) => ({ ...l, [key]: next }))
      }
    }
    Promise.all([worker(), worker(), worker()])
    // Anything still in flight is asked again by the next run.
    return () => {
      ctrl.abort()
      pending.forEach((k) => asked.current.delete(k))
    }
  }, [refs, canVerify])

  const statusOf = (r: Reference): Status => {
    const l = r.key ? lookups[r.key] : undefined
    if (l?.state === "not-found") return "missing"
    if (r.issues.length) return l?.state === "found" ? "off" : r.kind === "quote" ? "unverified" : "bad"
    if (l?.state === "checking") return "checking"
    if (l?.state === "found") return "verified"
    return "unverified"
  }
  const rows = refs.map((r) => ({ r, s: statusOf(r) })).sort((a, b) => RANK[a.s] - RANK[b.s] || a.r.start - b.r.start)
  const bad = rows.filter((x) => x.s === "bad" || x.s === "missing").length
  const unverified = rows.filter((x) => x.s === "unverified" || x.s === "off" || x.s === "checking").length
  const ok = rows.length - bad - unverified
  const summary = rows.length ? fill(m.summary, { bad, unverified, ok }) : m.none

  React.useEffect(() => {
    const t = setTimeout(() => setStatus(checked.trim() ? summary : ""), 700)
    return () => clearTimeout(t)
  }, [summary, checked])
  React.useEffect(() => setArmed(false), [checked])

  const set = (next: string, now = false) => {
    if (valueProp === undefined) setInner(next)
    onValueChange?.(next)
    if (now) setChecked(next)
  }

  // Ranges come from the last check; if typing moved on, find the same reference in the live text.
  const live = (r: Reference) => (value === checked ? r : findReferences(value.replace(/\r\n?/g, "\n"), { year }).find((x) => x.kind === r.kind && x.text === r.text))

  const repair = (r: Reference) => {
    const ref = live(r)
    if (!ref) return setChecked(value)
    const next = applyFix(value, ref)
    set(next, true)
    const first = findReferences(next, { year }).find((x) => x.fix !== undefined)
    requestAnimationFrame(() =>
      requestAnimationFrame(() => ((first && listRef.current?.querySelector<HTMLElement>(`[data-ref="${CSS.escape(first.id)}"] [data-fix]`)) || fieldRef.current)?.focus()),
    )
  }

  const show = (r: Reference) => {
    const ref = live(r)
    const el = fieldRef.current
    if (!ref || !el) return
    el.focus()
    el.setSelectionRange(ref.start, ref.end)
  }

  const submit = async () => {
    if (submitting) return
    setChecked(value)
    if (bad + unverified > 0 && !armed) {
      setArmed(true)
      if (!reduce && submitRef.current) animate(submitRef.current, { x: [0, -5, 5, -3, 0] }, { duration: 0.3 })
      return
    }
    setSubmitting(true)
    try {
      await onSubmit?.(value)
    } catch {
      // The caller reports its own failure; the button becomes usable again.
    } finally {
      setSubmitting(false)
      setArmed(false)
    }
  }

  const visible = all ? rows : rows.slice(0, Math.max(1, maxVisible))

  return (
    <div data-slot="ai-citation-check" data-state={bad ? "flagged" : unverified ? "unverified" : "clear"} className={cn("grid w-full min-w-0 gap-2", className)}>
      <textarea
        ref={fieldRef}
        id={id}
        value={value}
        rows={7}
        aria-invalid={bad > 0 || undefined}
        aria-describedby={[describedBy, `${id}-summary`].filter(Boolean).join(" ")}
        onChange={(e) => set(e.target.value)}
        onBlur={(e) => {
          onBlur?.(e)
          setChecked(e.currentTarget.value)
        }}
        onPaste={() => requestAnimationFrame(() => setChecked(fieldRef.current?.value ?? ""))}
        className={cn(
          "min-h-32 w-full resize-y rounded-md border bg-transparent px-3 py-2 text-base shadow-xs outline-none transition-colors focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-red-500/60 md:text-sm dark:bg-input/30",
          textareaClassName,
        )}
        {...props}
      />
      <p id={`${id}-summary`} className={cn("text-xs", bad ? "font-medium text-red-700 dark:text-red-400" : unverified ? "text-amber-700 dark:text-amber-400" : "text-muted-foreground")}>
        {summary}
      </p>

      {rows.length > 0 && (
        <ul ref={listRef} className="grid gap-1.5">
          <AnimatePresence initial={false}>
            {visible.map(({ r, s }, i) => {
              const Icon = ICON[r.kind]
              const l = r.key ? lookups[r.key] : undefined
              return (
                <motion.li
                  key={r.id}
                  data-ref={r.id}
                  layout={!reduce}
                  initial={reduce ? { opacity: 0 } : { opacity: 0, y: 4 }}
                  animate={{ opacity: 1, y: 0, transition: { delay: reduce ? 0 : Math.min(i, 5) * 0.04 } }}
                  exit={{ opacity: 0, transition: { duration: 0.12 } }}
                  className={cn("grid min-w-0 gap-1.5 rounded-md border p-2.5", TONE[s])}
                >
                  <div className="flex min-w-0 items-start gap-2">
                    <Icon aria-hidden className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
                    <div className="grid min-w-0 flex-1 gap-0.5">
                      <span className="flex flex-wrap items-center gap-x-2 text-xs">
                        <span className="text-muted-foreground">{m.kind[r.kind]}</span>
                        <span className={cn("inline-flex items-center gap-1 font-medium", PILL[s])}>
                          {s === "checking" ? <Loader2 aria-hidden className="size-3 animate-spin" /> : s === "verified" ? <Check aria-hidden className="size-3" /> : s === "unverified" || s === "off" ? <CircleHelp aria-hidden className="size-3" /> : <XCircle aria-hidden className="size-3" />}
                          {m.status[s]}
                        </span>
                      </span>
                      <span className={cn("line-clamp-2 text-sm break-words [overflow-wrap:anywhere]", (r.kind === "doi" || r.kind === "url" || r.kind === "marker") && "font-mono text-xs")}>{r.text}</span>
                      {r.issues.map((iss) => (
                        <span key={iss.code} className="text-xs text-muted-foreground">
                          {m.issue[iss.code] ? fill(m.issue[iss.code]!, iss.vars ?? {}) : iss.message}
                        </span>
                      ))}
                      {s === "missing" && <span className="text-xs text-muted-foreground">{fill(m.missing, { source: sourceName })}</span>}
                      {l?.state === "found" && l.title && (
                        <span className="flex min-w-0 items-center gap-1 text-xs text-muted-foreground">
                          {l.url ? (
                            <a href={l.url} target="_blank" rel="noreferrer" className="inline-flex min-w-0 items-center gap-1 underline-offset-2 outline-none hover:underline focus-visible:ring-[3px] focus-visible:ring-ring/50">
                              <span className="truncate">{l.title}</span>
                              <ExternalLink aria-hidden className="size-3 shrink-0" />
                            </a>
                          ) : (
                            <span className="truncate">{l.title}</span>
                          )}
                        </span>
                      )}
                    </div>
                  </div>
                  <div className="flex flex-wrap gap-1.5 pl-6">
                    {r.fix !== undefined && (
                      <button type="button" data-fix onClick={() => repair(r)} className={chip}>
                        {r.fix ? <Wrench aria-hidden className="size-3.5" /> : <Trash2 aria-hidden className="size-3.5" />}
                        {r.fix ? m.fix : m.remove}
                      </button>
                    )}
                    <button type="button" onClick={() => show(r)} className={chip}>
                      {m.show}
                    </button>
                  </div>
                </motion.li>
              )
            })}
          </AnimatePresence>
          {!all && rows.length > visible.length && (
            <li>
              <button type="button" onClick={() => setAll(true)} className={chip}>
                {fill(m.more, { count: rows.length - visible.length })}
              </button>
            </li>
          )}
        </ul>
      )}

      {onSubmit && (
        <div className="grid gap-1.5">
          <button
            ref={submitRef}
            type="button"
            disabled={submitting}
            aria-describedby={armed ? `${id}-confirm` : undefined}
            onClick={submit}
            className={cn(
              "inline-flex h-9 w-fit max-w-full items-center gap-2 rounded-md px-4 text-sm font-medium shadow-xs outline-none transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:opacity-60",
              armed ? "bg-destructive text-white hover:bg-destructive/90" : "bg-primary text-primary-foreground hover:bg-primary/90",
            )}
          >
            {submitting && <Loader2 aria-hidden className="size-4 animate-spin" />}
            {submitting ? m.submitting : armed ? m.submitAnyway : m.submit}
          </button>
          {armed && (
            <p id={`${id}-confirm`} role="alert" className="text-xs text-red-700 dark:text-red-400">
              {fill(m.confirm, { count: bad + unverified })}
            </p>
          )}
        </div>
      )}
      <span role="status" className="sr-only">{status}</span>
    </div>
  )
}

// Bollard UI — ai-citation-check · MIT licence · https://bollard-ui.vercel.app/components/ai-citation-check

export type RefKind = "doi" | "case" | "url" | "cite" | "quote" | "marker"
export type IssueCode = "doi-dash" | "doi-publisher" | "reporter-year" | "future-year" | "marker" | "unsourced-quote"

export interface Issue {
  code: IssueCode
  /** Plain-words reason, in English; the component can swap it via messages keyed by code. */
  message: string
  /** Values the message mentions, for translated messages. */
  vars?: Record<string, string | number>
}

export interface Reference {
  /** Stable for the same text at the same place. */
  id: string
  kind: RefKind
  /** The reference as written. */
  text: string
  start: number
  end: number
  issues: Issue[]
  /** What a lookup should search for: the DOI, the case citation or the URL. Null when nothing can be looked up. */
  key: string | null
  /** A one-tap repair: replace `text` with this. Empty string removes it. */
  fix?: string
}

/**
 * DOI registrant prefixes of the big publishers, and the journals that use them. "Nature", "Science" and "Cell"
 * only count as the journal when no capitalised word sits right before them, so "Computer Science",
 * "Environmental Science & Technology" (ACS) and "Human Nature" (Springer) aren't read as Science or Nature.
 */
const SOLO = String.raw`(?<![A-Z][\p{L}'’-]*[ \u00A0])`
const PUBLISHERS: { prefix: string; name: string; journals: RegExp }[] = [
  { prefix: "10.1038", name: "Springer Nature", journals: new RegExp(String.raw`${SOLO}\bNature(?! Communications? Reviews)\b|\bScientific Reports\b|\bNature Communications\b`, "u") },
  { prefix: "10.1126", name: "AAAS", journals: new RegExp(String.raw`${SOLO}\bScience(?: Advances| Translational Medicine)?\b(?!\s*(?:of|and|&|Direct)\b)`, "u") },
  { prefix: "10.1056", name: "NEJM Group", journals: /\b(?:N(?:ew)? ?Engl(?:and)? ?J(?:ournal)? ?(?:of )?Med(?:icine)?|NEJM)\b/i },
  { prefix: "10.1001", name: "the American Medical Association", journals: /\bJAMA\b/ },
  { prefix: "10.1136", name: "BMJ", journals: /\bBMJ\b|\bBritish Medical Journal\b/ },
  { prefix: "10.1371", name: "PLOS", journals: /\bPLo[Ss] (?:ONE|One|Biology|Medicine|Genetics)\b/ },
  { prefix: "10.1016", name: "Elsevier", journals: new RegExp(String.raw`\bThe Lancet\b|\bLancet\b|${SOLO}\bCell\b(?! Reports? Physical)`, "u") },
  { prefix: "10.1145", name: "ACM", journals: /\bCommunications of the ACM\b|\bACM Computing Surveys\b/ },
  { prefix: "10.1109", name: "IEEE", journals: /\bIEEE Transactions\b/ },
  { prefix: "10.1073", name: "PNAS", journals: /\bPNAS\b|\bProceedings of the National Academy of Sciences\b/ },
]

/** Federal reporters and the years they printed: a citation outside its reporter's years is a tell. */
// Years from Justia's reporter index (https://law.justia.com/cases/) and Wikipedia's Federal Reporter / Federal Supplement pages.
const REPORTERS: { re: RegExp; name: string; from?: number; to?: number; next?: string }[] = [
  { re: /^F\.\s?2d$/, name: "F.2d", from: 1924, to: 1993, next: "F.3d" },
  { re: /^F\.\s?3d$/, name: "F.3d", from: 1993, to: 2021, next: "F.4th" },
  { re: /^F\.\s?Supp\.$/, name: "F. Supp.", from: 1932, to: 1998, next: "F. Supp. 2d" },
  { re: /^F\.\s?4th$/, name: "F.4th", from: 2021 },
  { re: /^F\.\s?Supp\.\s?2d$/, name: "F. Supp. 2d", from: 1998, to: 2014, next: "F. Supp. 3d" },
  { re: /^F\.\s?Supp\.\s?3d$/, name: "F. Supp. 3d", from: 2014 },
  { re: /^F\.\s?App(?:'|’)x$/, name: "F. App'x", from: 2001, to: 2021 },
]

const DASHES = /[\u2010-\u2015\u2212]/
const DOI = /\b10\.\d{4,9}\/(?:[^\s"<>()[\]{}]|\(\w{1,6}\))*[^\s"<>()[\]{}.,;:]/g
const CASE = /\b(\d{1,4})\s+(U\.\s?S\.|S\.\s?Ct\.|F\.\s?(?:2d|3d|4th)|F\.\s?Supp\.(?:\s?[23]d)?|F\.\s?App(?:'|’)x)\s+(\d{1,5})(?:,\s*\d{1,5}(?:[–-]\d+)?)?\s*\(([^()]{0,40}?)(\d{4})\)/g
const URL = /\bhttps?:\/\/[^\s<>"'()]+[^\s<>"'().,;:!?]/g
const AUTHOR_YEAR = /\(([A-Z][\p{L}'’-]+(?:\s(?:et al\.|and|&)\s?[A-Z]?[\p{L}'’-]*)?),?\s(\d{4})[a-z]?\)/gu
const MARKERS = /:?contentReference\[oaicite:\d+\]\{index=\d+\}|【\d+(?::\d+)?†[^】]{0,40}】|\uE200cite(?:\uE202[\w-]+)+\uE201|oai_citation:\d+‡[^\s)\]]*|\[cite(?:_start|_end|:\s*[\d, ]+)\]|\bturn\d+(?:search|news|view|file)\d+\b/g
const QUOTE = /[“"]([^“”"\n]{40,})[”"]/g
const SOURCE_NEAR = /\([^()]*\d{4}[a-z]?\)|\[\d+(?:[,–-]\s?\d+)*\]|https?:\/\/|\b10\.\d{4,9}\/|\d+\s+(?:U\.\s?S\.|F\.)|\b(?:said|wrote|according to|told)\s+[A-Z]/

/**
 * Finds the references in AI-written text and flags the ones that look made up: a DOI whose prefix
 * doesn't belong to the journal it names, a dash inside a DOI, a case cited to a reporter that wasn't
 * printing that year (F.3d for 2022), a year in the future, leftover chatbot citation markers
 * (oaicite, 【4†source】), and long quotes with no source nearby. Everything with a `key` can be
 * looked up; nothing here claims a reference is real. Never throws.
 */
export function findReferences(input: string, opts: { year?: number } = {}): Reference[] {
  if (typeof input !== "string" || !input) return []
  const text = input
  const year = opts.year && Number.isFinite(opts.year) ? opts.year : new Date().getFullYear()
  const refs: Reference[] = []
  const taken = (s: number, e: number) => refs.some((r) => s < r.end && e > r.start)
  const push = (r: Omit<Reference, "id">) => {
    if (!taken(r.start, r.end)) refs.push({ ...r, id: `${r.kind}-${r.start}-${r.text.length}` })
  }
  const future = (y: number): Issue[] => (y > year ? [{ code: "future-year", message: `${y} hasn't happened yet.`, vars: { year: y } }] : [])

  for (const m of text.matchAll(MARKERS)) push({ kind: "marker", text: m[0], start: m.index, end: m.index + m[0].length, key: null, fix: "", issues: [{ code: "marker", message: "A chatbot's citation marker. It points to nothing outside that chat." }] })

  // DOIs, including ones where a dash replaced the hyphen ("10.1038/s41586–021").
  const doiText = text.replace(/\b10\.\d{4,9}\/\S+/g, (s) => s.replace(new RegExp(DASHES.source, "g"), "-"))
  const dois = [...doiText.matchAll(DOI)]
  for (const [i, m] of dois.entries()) {
    const raw = text.slice(m.index, m.index + m[0].length)
    const issues: Issue[] = []
    let fix: string | undefined
    if (DASHES.test(raw)) {
      issues.push({ code: "doi-dash", message: "DOIs use plain hyphens. A long dash here usually means the DOI was retyped, not copied.", vars: {} })
      fix = raw.replace(new RegExp(DASHES.source, "g"), "-")
    }
    const prefix = m[0].split("/")[0]
    // A reference names its journal before the DOI, or in a parenthesis right after it. Look no further
    // back than the line start or the previous DOI, so a neighbour's journal never counts.
    const lineStart = text.lastIndexOf("\n", m.index) + 1
    const prev = dois[i - 1]
    const before = text.slice(Math.max(lineStart, m.index - 120, prev ? prev.index + prev[0].length : 0), m.index)
    const paren = text.slice(m.index + raw.length).match(/^\s*\(([^()\n]{0,40})\)/)?.[1] ?? ""
    const near = `${before} ${paren}`
    const named = PUBLISHERS.find((p) => p.journals.test(near))
    if (named && named.prefix !== prefix) {
      const owner = PUBLISHERS.find((p) => p.prefix === prefix)
      const journal = near.match(named.journals)?.[0] ?? named.name
      issues.push({ code: "doi-publisher", message: `It names ${journal}, but ${prefix} belongs to ${owner ? owner.name : "a different publisher"}. ${journal} DOIs start ${named.prefix}.`, vars: { journal, prefix, expected: named.prefix } })
    }
    const y = paren.match(/\b(?:19|20)\d{2}\b/)?.[0] ?? before.slice(-40).match(/\b(?:19|20)\d{2}\b(?!.*\b(?:19|20)\d{2}\b)/)?.[0]
    if (y) issues.push(...future(Number(y)))
    push({ kind: "doi", text: raw, start: m.index, end: m.index + raw.length, key: m[0].toLowerCase(), issues, fix })
  }

  for (const m of text.matchAll(CASE)) {
    const y = Number(m[5])
    const reporter = REPORTERS.find((r) => r.re.test(m[2].trim()))
    const issues: Issue[] = [...future(y)]
    if (reporter && y <= year && ((reporter.to && y > reporter.to) || (reporter.from && y < reporter.from)))
      issues.push({ code: "reporter-year", message: `${reporter.name} ${reporter.to && y > reporter.to ? `stopped in ${reporter.to}${reporter.next ? `; a ${y} case would be in ${reporter.next}` : ""}` : `started in ${reporter.from}`}.`, vars: { reporter: reporter.name, year: y } })
    // Take the case name back to the start of the sentence or line ("Varghese v. China Southern Airlines Co., ").
    const before = text.slice(Math.max(0, m.index - 120), m.index)
    const clause = before.split(/[;:]\s|\.\s+(?=[A-Z])(?<!\bv\.\s+)|\n/).pop() ?? ""
    const name = clause.replace(/^\s*(?:(?:See|see|Cf\.|cf\.|But|but|E\.g\.|e\.g\.|also|Accord|accord),?\s+)+/, "").match(/([A-Z][\w.'’&-]*(?:\s+[\w.'’&-]+){0,8}\s+v\.\s+[\w.'’&,-]+(?:\s+[\w.'’&,-]+){0,8}?,?\s*)$/)
    const start = name ? m.index - name[1].length : m.index
    push({ kind: "case", text: text.slice(start, m.index + m[0].length), start, end: m.index + m[0].length, key: `${m[1]} ${m[2].replace(/\s+/g, " ")} ${m[3]}`, issues })
  }

  for (const m of text.matchAll(URL)) {
    if (/doi\.org\//i.test(m[0]) && refs.some((r) => r.kind === "doi" && r.start >= m.index && r.end <= m.index + m[0].length)) continue
    push({ kind: "url", text: m[0], start: m.index, end: m.index + m[0].length, key: m[0], issues: [] })
  }

  for (const m of text.matchAll(AUTHOR_YEAR)) {
    const y = Number(m[2])
    if (y > year) push({ kind: "cite", text: m[0], start: m.index, end: m.index + m[0].length, key: null, issues: future(y) })
  }

  for (const m of text.matchAll(QUOTE)) {
    const words = m[1].trim().split(/\s+/).length
    if (words < 25) continue
    const paraStart = Math.max(text.lastIndexOf("\n\n", m.index), 0)
    const nextBreak = text.indexOf("\n\n", m.index + m[0].length)
    const para = text.slice(paraStart, nextBreak < 0 ? text.length : nextBreak)
    if (SOURCE_NEAR.test(para.replace(m[0], ""))) continue
    push({ kind: "quote", text: m[0], start: m.index, end: m.index + m[0].length, key: null, issues: [{ code: "unsourced-quote", message: `A ${words}-word quote with nothing saying who said it or where.`, vars: { words } }] })
  }

  return refs.sort((a, b) => a.start - b.start)
}

/** Applies a reference's fix to the text, only if the reference is still where it was found. */
export function applyFix(text: string, ref: Pick<Reference, "start" | "end" | "text" | "fix">): string {
  if (ref.fix === undefined || text.slice(ref.start, ref.end) !== ref.text) return text
  let before = text.slice(0, ref.start)
  let after = text.slice(ref.end)
  // Removing a marker shouldn't leave a double space or a space before punctuation.
  if (ref.fix === "") {
    if (/\s$/.test(before) && /^[\s.,;:!?)]/.test(after)) before = before.replace(/[ \t]+$/, "")
    if (/^[ \t]/.test(after) && /^\s*$/.test(before.slice(-1))) after = after.replace(/^[ \t]+/, "")
  }
  return before + ref.fix + after
}
